def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]
    total = v1 + v2 + v3
    return {
        "value": round(total),
        "trace": {
            "v1": v1,
            "v2": v2,
            "v3": v3,
            "sum": total,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }
